<script lang="ts">
 import { onMount } from 'svelte';
 import { goto } from '$app/navigation';
 import QRCode from 'qrcode';
 import { connectFirebase } from '$lib/backend/firebase';
 import { createRoom } from '$lib/backend/repository';
 import { GameSession, firestoreTransport } from '$lib/backend/session';
 import CardFace from './CardFace.svelte';
 import { definitions, complete, score, canPlace, type Piece, type View, type Target, type Command } from '$lib/game/engine';
 import { cards } from '$lib/game/cards';
 let { mode='lobby' }: {mode?:'lobby'|'table'|'hand'}=$props();
 let room=$state(''), name=$state(''), view=$state<View|null>(null), error=$state(''), busy=$state(false), connected=$state(false);
 let selected=$state<Piece|null>(null), targets=$state<Target[]>([]), destinations=$state<number[]>([]), wildAs=$state('green-tea'), bonus=$state<'draw'|'play'>('draw'), discarding=$state(false), showDiscard=$state(false), detail=$state<Piece|null>(null);
 let qr=$state(''), joinUrl=$state(''), address=$state(''), target=$state(5), localRevision=-1;
 let syncPending=$state(0); let session:GameSession|undefined; let uid='';
 let active=$derived(view?.players[view.active]);let me=$derived(view?.players.find(p=>p.id===view?.you));
 let myTurn=$derived(!!me&&active?.id===me.id);let choosing=$derived(view?.phase==='choice'&&view.pending?.victim===view.you);
 let selectedDef=$derived(selected?definitions[selected.type]:null);
 let prompt=$derived(choosing?`Choose ${view?.pending?.choice==='milk'?'one Milk card':'an incomplete drink'} to discard.`:selected?selected.type==='recycle'?'Tap a card in the discard pile.':selected.type==='sabobatage'?`Choose five ingredients. ${targets.length}/5 selected; reactions start after the fifth.`:selected.type==='sugar-and-ice'||selected.type==='tea-party'?targets.length?`Choose your destination drink${targets.length>1?'s, in order':''}. ${destinations.length}/${targets.length} placed.`:selected.type==='tea-party'?'Choose one or two tea cards, then tap your destination drinks.':'Tap an opponent’s ingredient, then your destination drink.':['bogo','pos-down','lactose-intolerant','untrained-employee'].includes(selected.type)?'Tap the shop you want to target.':selected.type==='health-inspector'?'Tap a topping or flavor to target its type.':'Tap one of your drink slots to place this card.':view?.phase==='reaction'?'All targets are chosen. Play Customer Loyalty or pass.':myTurn?view?.phase==='draw'?'Tap the deck to draw for your turn.':`${view?.plays} plays left. Tap a hand card to play it.`:`${active?.name??'The next shop'} is taking a turn.`);
 function accept(next:View){if(next.revision!==localRevision){if(localRevision>=0){selected=null;targets=[];destinations=[];}localRevision=next.revision;view=next;}else view=next;}
 async function create(){busy=true;error='';try{const {db,uid}=await connectFirebase();const code=await createRoom(db,uid);await goto(`/table/?room=${code}`);}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function join(){error='';try{session?.send({type:'player/joined',name});}catch(e){error=(e as Error).message;}}
 function command(cmd:Command|{type:'undo'}){if(!view||!session)return;error='';try{if(cmd.type==='undo')session.undo();else session.send({type:'game/command',command:cmd});selected=null;targets=[];destinations=[];discarding=false;}catch(e){error=(e as Error).message;}}
 function cancel(){selected=null;targets=[];destinations=[];discarding=false;}
 async function play(extra:Partial<Command>={}){if(!selected)return;await command({type:'play',card:selected.uid,targets,destinations,wildAs,bonus,...extra});}
 function handCard(c:Piece){detail=c;if(discarding){void command({type:'discard',card:c.uid});return;}if(view?.phase==='reaction'&&c.type==='customer-loyalty'){const affected=view.pending?.victim===view.you||view.pending?.targets.some(t=>t.player===view!.you);void command({type:'counter',card:c.uid,counterLast:!affected||view.pending?.protected.includes(view.you!)});return;}if(!myTurn||view?.phase!=='play')return;if(selected?.uid===c.uid){cancel();return;}selected=c;targets=[];destinations=[];if(c.type==='5-star-review')void play();if(c.type==='recycle')showDiscard=true;}
 function targetCard(t:Target,c:Piece){detail=c;if(choosing){void command({type:'choose',targets:[t]});return;}if(!selected)return;
  if(selected.type==='sabobatage'){targets=targets.some(x=>x.card===t.card)?targets.filter(x=>x.card!==t.card):[...targets,t];if(targets.length===5)void play();}
  else if(selected.type==='health-inspector')void play({targets:[t]});
  else if(selected.type==='sugar-and-ice') {targets=[t];destinations=[];}
  else if(selected.type==='tea-party'){targets=targets.some(x=>x.card===t.card)?targets.filter(x=>x.card!==t.card):targets.length<2?[...targets,t]:targets;destinations=[];}
 }
 function slotClick(player:string,slot:number){if(choosing&&view?.pending?.choice==='drink'){void command({type:'choose',targets:[{player,slot}]});return;}if(player!==view?.you||!selected)return;if(['sugar-and-ice','tea-party'].includes(selected.type)){if(!targets.length)return;destinations=[...destinations,slot];if(destinations.length===targets.length)void play();}else void play({slot});}
 function targetPlayer(id:string){if(selected&&['bogo','pos-down','lactose-intolerant','untrained-employee'].includes(selected.type))void play({victim:id});}
 function fit(slot:number){if(!selected||!me)return false;const c=targets.length?view?.players.find(p=>p.id===targets[destinations.length]?.player)?.drinks[targets[destinations.length]?.slot]?.cards.find(c=>c.uid===targets[destinations.length]?.card):selected;if(!c)return false;return canPlace(me.drinks[slot],{...c,...(c.type==='wild-ingredient'?{as:wildAs}:{})});}
 async function updateQR(){if(!room||!address)return;joinUrl=`${location.protocol}//${address}/hand/?room=${room}`;qr=await QRCode.toDataURL(joinUrl,{width:220,margin:2,color:{dark:'#583c32',light:'#fffaf0'}});}
 onMount(()=>{const params=new URLSearchParams(location.search);room=(params.get('room')??'').toUpperCase();address=location.host;void updateQR();let disposed=false;
  if(mode!=='lobby'&&room)void connectFirebase().then(services=>{if(disposed)return;uid=services.uid;session=new GameSession(firestoreTransport(services.db,room),uid,mode==='table',state=>{accept(state.view);connected=state.connected;syncPending=state.pending;if(state.error)error=state.error;},localStorage,`sabobatage:events:v1:${room}:${uid}`);session.start();}).catch(e=>error=e.message);
  return()=>{disposed=true;session?.stop();};
 });
</script>
<svelte:head><title>{mode==='table'?'Shared table':mode==='hand'?'Your hand':'Play'} · Sabobatage</title></svelte:head>
<main id="main" class="game-page" class:shared-table={mode==='table'}>
 {#if mode==='lobby'}
  <section class="game-welcome"><p class="eyebrow">OPEN YOUR BOBA SHOP</p><h1>One table.<br/><em>A few secret recipes.</em></h1><p>Gather 2–5 players. Keep the shared table on a big screen and your cards on your phone.</p><button class="primary-button" disabled={busy} onclick={create}>Create a table ↗</button><form onsubmit={e=>{e.preventDefault();void goto(`/hand/?room=${room.trim().toUpperCase()}`);}}><label>Room code<input aria-label="Room code" bind:value={room} maxlength="6" placeholder="ABC234" required/></label><button class="game-button">Join on this device</button></form><p class="small">Private hands, instant moves, and undo when someone makes a slip.</p></section>
 {:else if !room}<section class="game-welcome"><h1>Find your table</h1><a href="/play/" class="primary-button">Create or join a table</a></section>
 {:else}
  <header class="game-heading"><div><p class="eyebrow">{mode==='table'?'SHARED TABLE':'PRIVATE HAND'} · {room}</p><h1>{me?.name??'The boba shop'}</h1></div><span class:offline={!connected} class="connection">{syncPending?`◌ Syncing ${syncPending} move${syncPending===1?'':'s'}`:connected?'● Synced':'○ Connecting…'}</span><a href="/play/">Other tables</a></header>
  {#if view}
   {#if mode==='hand'&&!me}<form class="join-shop" onsubmit={e=>{e.preventDefault();void join();}}><h2>Take a seat</h2><label>Your shop name<input aria-label="Your shop name" bind:value={name} maxlength="32" required placeholder="Peach Please"/></label><button class="primary-button" disabled={busy||view.phase!=='lobby'}>Join table</button>{#if view.phase!=='lobby'}<p>This game has started. Reopen it on the phone you used to join.</p>{/if}</form>{/if}
   {#if view.phase==='lobby'}
    <section class="table-lobby"><div><p class="eyebrow">{view.players.length}/5 SHOPS OPEN</p><h2>Everyone brings<br/>their own secrets.</h2><ul>{#each view.players as p}<li>● {p.name}{p.id===view.you?' · you':''}</li>{/each}</ul>{#if !view.players.length}<p>Scan the code with each player’s phone to join.</p>{/if}{#if view.host}<label>Drinks to win<select bind:value={target}><option value={3}>3 · Quick game</option><option value={4}>4 drinks</option><option value={5}>5 · Full game</option></select></label><button class="primary-button" disabled={view.players.length<2||busy} onclick={()=>command({type:'start',target})}>Open the shops →</button>{:else}<p>Waiting for the host to open the shops.</p>{/if}</div>{#if mode==='table'}<div class="join-code">{#if qr}<img src={qr} alt={`Scan to join room ${room}`} width="220" height="220"/>{/if}<strong>{room}</strong><a href={joinUrl}>{joinUrl}</a><p>Scan to open your private hand.</p><label>Address for phones<input aria-label="Address for phones" bind:value={address} onchange={updateQR}/></label>{#if address.startsWith('127.')||address.startsWith('localhost')}<p>Use the Network address printed by the dev server so phones can reach this table.</p>{/if}<a href={`/hand/?room=${room}`} target="_blank" rel="noreferrer">Open a hand on this device ↗</a></div>{/if}</section>
   {:else}
    <section class="turn-bar" aria-live="polite"><div><p class="eyebrow">{view.phase==='won'?'SHOP OF THE DAY':view.phase==='reaction'?'REACTION WINDOW':view.phase==='choice'?'PLAYER’S CHOICE':`${active?.name}’S TURN`}</p><h2>{view.phase==='won'?`${view.players.find(p=>p.id===view!.winner)?.name} wins!`:mode==='table'?view.pending?`${definitions[view.pending.card.type].name} · ${view.phase==='choice'?'waiting for a choice':'reactions open'}`:view.phase==='draw'?`${active?.name} draws next · ${view.target} drinks to win`:`${view.plays} plays left · ${view.target} drinks to win`:prompt}</h2></div><div class="turn-actions">{#if view.canUndo}<button class="game-button" disabled={busy} onclick={()=>command({type:'undo'})}>↶ Undo {view.undoLabel}</button>{/if}{#if selected||discarding}<button class="game-button" onclick={cancel}>Cancel selection</button>{/if}{#if myTurn&&view.phase==='play'}<button class="game-button" disabled={busy||me!.handCount>7} onclick={()=>command({type:'end'})}>End turn →</button>{/if}</div></section>
    {#if view.pending}<section class="reaction-strip"><b>{view.players.find(p=>p.id===view!.pending!.actor)?.name} played {definitions[view.pending.card.type].name}.</b><span>{view.pending.targets.length?`${view.pending.targets.length} ingredients targeted.`:`Target: ${view.players.find(p=>p.id===view!.pending!.victim)?.name}`}</span>{#if view.phase==='reaction'}<span>{view.pending.passed.length}/{view.players.length} players passed</span>{#if me}<button class="game-button" disabled={busy||view.pending.passed.includes(me.id)} onclick={()=>command({type:'pass'})}>{view.pending.passed.includes(me.id)?'Waiting for reactions…':'Pass reaction'}</button>{#if view.pending.chainTarget&&view.hand.some(c=>c.type==='customer-loyalty')}<button class="game-button" disabled={busy} onclick={()=>command({type:'counter',card:view!.hand.find(c=>c.type==='customer-loyalty')!.uid,counterLast:true})}>Counter last Loyalty</button>{/if}{/if}{/if}</section>{/if}
    <div class="pile-bar"><button class="deck-pile" disabled={!myTurn||view.phase!=='draw'||busy} onclick={()=>command({type:'draw'})}><span>● ● ●</span><b>{myTurn&&view.phase==='draw'?'Draw cards':'Draw pile'}</b><small>{view.deckCount} cards</small></button>{#if selected?.type==='tea-party'&&targets.length>destinations.length&&!me?.drinks.some((_,i)=>fit(i))}<button class="game-button" onclick={()=>{destinations=[...destinations,-1];if(destinations.length===targets.length)void play();}}>Discard tea that cannot fit</button>{/if}<button class="game-button" onclick={()=>showDiscard=!showDiscard}>Discard pile · {view.discard.length} {showDiscard?'▴':'▾'}</button>{#if selected?.type==='boba'||selected?.type==='sugar-and-ice'}<label>Boba bonus<select bind:value={bonus}><option value="draw">Draw one</option><option value="play">Play one extra</option></select></label>{/if}</div>
    {#if showDiscard}<section class="discard-tray" aria-label="Discard pile">{#each view.discard as c}<button class="mini-card" onclick={()=>{detail=c;if(selected?.type==='recycle')void play({targets:[{player:'',slot:0,card:c.uid}]});}}><CardFace card={definitions[c.type]}/></button>{:else}<p>The discard pile is empty.</p>{/each}</section>{/if}
    {#if me}<section class="private-hand"><div class="hand-heading"><h2>Your hand <span>{view.hand.length}/7</span></h2>{#if myTurn&&view.phase==='play'&&me.handCount>7}<button class="game-button" class:chosen={discarding} onclick={()=>{cancel();discarding=true;}}>Discard {me.handCount-7} · tap cards</button>{/if}</div><div class="hand-cards">{#each view.hand as c (c.uid)}<button class="hand-card" class:chosen={selected?.uid===c.uid} aria-label={`Play ${definitions[c.type].name}`} aria-pressed={selected?.uid===c.uid} disabled={busy} draggable={myTurn&&view.phase==="play"&&definitions[c.type].category!=="Action"} ondragstart={e=>{selected=c;targets=[];destinations=[];e.dataTransfer?.setData('text/plain',c.uid);}} onclick={()=>handCard(c)}><CardFace card={definitions[c.type]}/></button>{/each}</div>{#if detail}<p class="card-help"><b>{definitions[detail.type].name}:</b> {definitions[detail.type].effect}</p>{/if}</section>{/if}
    <section class="shops" aria-label="Players’ tables">{#each view.players as player,i}<article class="shop" class:active-shop={active?.id===player.id} class:my-shop={me?.id===player.id} style={`--shop-color:${['#eec4cd','#c5d398','#c9b4dc','#eac48c','#a6cdd0'][i]}`}><header><button class="shop-name" onclick={()=>targetPlayer(player.id)}>{player.name}{player.id===view.you?' · you':''}</button><span>{player.drinks.filter(complete).length}/{view.target} drinks · {player.handCount} private cards{player.skip?' · skips next turn':''}</span></header><div class="drink-slots">{#each player.drinks as drink,slot}<div class="drink-slot" class:completed={complete(drink)} class:fits={player.id===view.you&&fit(slot)} role="group" aria-label={`${player.name} drink ${slot+1}`} ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();slotClick(player.id,slot);}}><button class="slot-label" onclick={()=>slotClick(player.id,slot)} aria-label={`${player.name} drink ${slot+1}${drink.cards.length?'':' empty slot'}`}>#{slot+1} {complete(drink)?'✓ Complete':drink.cards.length?'Brewing':'＋ New drink'}</button><div class="ingredient-stack">{#each drink.cards as c}<button class="table-card" class:targeted={targets.some(t=>t.card===c.uid)||view.pending?.targets.some(t=>t.card===c.uid)} aria-label={`${definitions[c.type].name} in ${player.name} drink ${slot+1}`} onclick={()=>{if(player.id===view!.you&&selected&&!['sabobatage','health-inspector','sugar-and-ice','tea-party'].includes(selected.type)&&!choosing)slotClick(player.id,slot);else targetCard({player:player.id,slot,card:c.uid},c);}}><CardFace card={definitions[c.type]}/>{#if c.as}<span class="wild-label">As {definitions[c.as].name}</span>{/if}</button>{/each}</div>{#each drink.protection as protection}<span class="protection">{protection.type==='straw'?'✦ Straw':'◈ Bobasurance'}</span>{/each}{#if player.id===view.you&&selected}<button class="place-here" onclick={()=>slotClick(player.id,slot)}>Place here</button>{/if}</div>{/each}</div></article>{/each}</section>
    {#if mode==='table'}<p class="table-privacy">Hands stay on players’ phones. Room {room} · <a href={joinUrl}>Phone link</a></p>{/if}
    <details class="game-log"><summary>Shop journal · {view.log.length} events</summary><ol>{#each view.log.slice().reverse() as entry}<li>{entry}</li>{/each}</ol></details>
   {/if}
  {:else}<p>Connecting to room {room}…</p>{/if}
 {/if}
 {#if error}<div class="game-error" role="alert">{error}<button aria-label="Dismiss error" onclick={()=>error=''}>✕</button></div>{/if}
</main>
